import{Qo as m,Zo as l$1}from"./chunk-DmxuwMFU.js";var c={first_days:`Nos primeiros dias`,first_weeks:`Nas primeiras semanas`};var l=[{id:`breathe`,phase:`first_days`,icon:`heart`,title:`Respire: ninguém sabe tudo no começo`,why:`Cuidar se aprende aos poucos. Escolha uma coisa por dia.`,todo:[`Anote o que mais preocupa você agora, para tirar da cabeça.`,`Comece pelo que não pode esperar: remédios e consultas.`,`Aceite ajuda quando alguém oferecer.`],link:{label:`Ver Cuidar de mim`,path:`/cuidador/cuidar-de-mim`}},{id:`health_info`,phase:`first_days`,icon:`clipboard-list`,title:`Junte as informações de saúde`,why:`Com tudo em um lugar só, você responde rápido na consulta e na emergência.`,todo:[`Nome e telefone dos médicos que acompanham a pessoa.`,`Condições de saúde e alergias.`,`Cartão do SUS, documento com foto e a carteirinha do convênio, se houver.`,`Receitas e exames recentes, juntos em uma pasta.`],link:{label:`Abrir Meu perfil`,path:`/cuidador/mais/perfil`}},{id:`medicines`,phase:`first_days`,icon:`pill`,title:`Organize os remédios`,why:`Trocar horário ou dose é um dos erros mais comuns no cuidado em casa.`,todo:[`Faça a lista: nome, dose e horário de cada remédio.`,`Confira a lista com o médico ou com o farmacêutico.`,`Nunca mude a dose nem pare um remédio sem orientação.`,`Guarde os remédios longe do calor, da umidade e do alcance de crianças.`],link:{label:`Cadastrar os remédios`,path:`/cuidador/rotina/remedios`}},{id:`emergency`,phase:`first_days`,icon:`phone-call`,title:`Saiba o que fazer numa emergência`,why:`Na hora do susto, ter o caminho pronto faz diferença.`,todo:[`Emergência de saúde: ligue para o SAMU, no 192.`,`Deixe a lista de remédios e os documentos fáceis de achar.`,`Combine com alguém de confiança quem você avisa primeiro.`],link:{label:`Ver Ajuda agora`,path:`/cuidador/ajuda-agora`}},{id:`agenda`,phase:`first_weeks`,icon:`calendar-days`,title:`Monte a agenda`,why:`Consultas, exames e terapias em um só calendário, sem depender da memória.`,todo:[`Anote cada consulta com dia, hora e endereço.`,`Leve as suas dúvidas escritas para a consulta.`,`Peça a receita nova antes de o remédio acabar.`],link:{label:`Abrir a Agenda`,path:`/cuidador/rotina/agenda`}},{id:`safe_home`,phase:`first_weeks`,icon:`house`,title:`Deixe a casa mais segura`,why:`Pequenas mudanças evitam quedas, que são comuns nessa fase da vida.`,todo:[`Tire tapetes soltos e objetos do caminho.`,`Deixe uma luz acesa à noite no caminho até o banheiro.`,`Barras de apoio e piso antiderrapante no banheiro ajudam muito.`,`Prefira calçados fechados, com sola que não escorrega.`]},{id:`share`,phase:`first_weeks`,icon:`users`,title:`Divida o cuidado`,why:`Ninguém dá conta sozinho por muito tempo.`,todo:[`Converse com a família sobre quem pode ajudar, e em quê.`,`Combine dias e tarefas, mesmo as pequenas.`,`Compartilhe a rotina pelo aplicativo com quem ajuda você.`],link:{label:`Abrir Família`,path:`/cuidador/mais/familia`}},{id:`support_network`,phase:`first_weeks`,icon:`landmark`,title:`Conheça a rede de apoio`,why:`Existem serviços públicos e profissionais que ajudam quem cuida.`,todo:[`A Unidade Básica de Saúde (UBS) do bairro acompanha a saúde da pessoa idosa.`,`O CRAS do bairro orienta sobre direitos e benefícios sociais.`,`Na Rede da Nexus você encontra profissionais para serviços em casa.`],link:{label:`Abrir a Rede`,path:`/cuidador/rede`}},{id:`self_care`,phase:`first_weeks`,icon:`hand-heart`,title:`Cuide de você também`,why:`O seu descanso faz parte do cuidado.`,todo:[`Reserve um tempo só seu, mesmo que seja curto.`,`Durma e se alimente o melhor que puder.`,`Se o cansaço pesar, fale com alguém. O CVV atende pelo 188, a qualquer hora, sem custo.`],link:{label:`Ver Como estou`,path:`/cuidador/cuidar-de-mim/como-estou`}}];var p=[{id:`app`,title:`Sobre o aplicativo`,icon:`circle-help`,items:[{id:`replace_doctor`,question:`O aplicativo substitui o médico ou a equipe de saúde?`,answer:[`Não. Ele ajuda a organizar a rotina e a falar com a Nexus. Dúvidas sobre saúde, remédios e tratamento são com os profissionais que acompanham a pessoa.`]},{id:`privacy`,question:`Meus dados ficam guardados com segurança? Quem vê?`,answer:[`Você decide o que autoriza. A equipe da Nexus vê só o que precisa para cuidar de você.`,`Em Privacidade e meus dados você revê as autorizações e pode pedir uma cópia ou a eliminação dos seus dados.`],link:{label:`Abrir Privacidade e meus dados`,path:`/cuidador/mais/privacidade`}},{id:`text_size`,question:`Como deixo a letra maior?`,answer:[`Em Mais, no painel Tamanho da letra, escolha Grande ou Bem grande. Vale na hora, no aplicativo inteiro.`],link:{label:`Abrir Mais`,path:`/cuidador/mais`}},{id:`cost`,question:`Quanto custa usar?`,answer:[`O plano Livre não tem custo. Em Meu plano você vê o seu plano e tudo o que ele inclui.`],link:{label:`Abrir Meu plano`,path:`/cuidador/mais/plano`}}]},{id:`routine`,title:`Remédios e rotina`,icon:`pill`,items:[{id:`mark_given`,question:`Como anoto que dei um remédio?`,answer:[`Em Hoje, toque em Dei ao lado do remédio. Se tocou por engano, toque em Desfazer, logo abaixo.`],link:{label:`Abrir Hoje`,path:`/cuidador/hoje`}},{id:`missed_dose`,question:`Esqueci de dar um remédio. O que eu faço?`,answer:[`Não dobre a dose por conta própria. Cada remédio tem uma orientação diferente: ligue para o médico ou pergunte ao farmacêutico como seguir.`]},{id:`appointments`,question:`Posso anotar consultas e exames?`,answer:[`Sim. Em Rotina, na Agenda, toque em Adicionar compromisso. Ele aparece em Hoje no dia certo.`],link:{label:`Abrir a Agenda`,path:`/cuidador/rotina/agenda`}},{id:`family`,question:`Outra pessoa da família pode acompanhar a rotina?`,answer:[`Sim. Em Família você compartilha a rotina com quem ajuda você.`],link:{label:`Abrir Família`,path:`/cuidador/mais/familia`}}]},{id:`you`,title:`Cuidar de você`,icon:`hand-heart`,items:[{id:`tired`,question:`Me sinto muito cansado(a). Isso é normal?`,answer:[`É comum quem cuida se sentir cansado, irritado ou triste em alguns dias. Isso não quer dizer que você está fazendo algo errado.`,`Em Como estou você conta como anda o seu cansaço, e a equipe da Nexus pode conversar com você.`],link:{label:`Abrir Como estou`,path:`/cuidador/cuidar-de-mim/como-estou`}},{id:`distress`,question:`Estou em sofrimento agora. Com quem falo?`,answer:[`O CVV atende pelo telefone 188, a qualquer hora, sem custo. Se houver risco de vida, ligue para o SAMU, no 192.`],link:{label:`Abrir Ajuda agora`,path:`/cuidador/ajuda-agora`}},{id:`psychologist`,question:`Como converso com um psicólogo da Nexus?`,answer:[`Em Cuidar de mim, toque em Conversar com um psicólogo e escolha um horário.`],link:{label:`Conversar com um psicólogo`,path:`/cuidador/cuidar-de-mim/atendimento`},requires:`individual_session`},{id:`group_therapy`,question:`O que é a terapia em grupo?`,answer:[`Encontros com um psicólogo da Nexus e outras pessoas que também cuidam, em turma pequena, para conversar sobre o que vocês sentem.`],link:{label:`Ver os encontros`,path:`/cuidador/cuidar-de-mim/grupos`},requires:`group_therapy`},{id:`training`,question:`O que são as capacitações?`,answer:[`Encontros para aprender a cuidar com mais segurança, como primeiros socorros, banho no leito e prevenção de quedas, com a equipe e profissionais parceiros.`],link:{label:`Ver os encontros`,path:`/cuidador/cuidar-de-mim/grupos`}}]},{id:`emergency`,title:`Emergências`,icon:`siren`,items:[{id:`when_samu`,question:`Quando devo ligar para o SAMU, no 192?`,answer:[`Em situações como estas:`],list:[`desmaio ou dificuldade para acordar;`,`falta de ar forte;`,`dor forte no peito;`,`boca torta, fraqueza de um lado do corpo ou fala enrolada de repente;`,`queda com machucado sério ou dor forte para se mexer;`,`sangramento que não para.`],link:{label:`Abrir Ajuda agora`,path:`/cuidador/ajuda-agora`}},{id:`ready`,question:`O que deixo pronto para uma emergência?`,answer:[`Em um lugar fácil de achar:`],list:[`a lista de remédios atualizada;`,`documentos e o cartão do SUS;`,`telefones da família e dos médicos;`,`condições de saúde e alergias anotadas.`]},{id:`violence`,question:`Suspeito de violência ou maus-tratos contra a pessoa idosa. O que eu faço?`,answer:[`Ligue para o Disque 100. A denúncia pode ser anônima. Em perigo imediato, ligue para a Polícia Militar, no 190.`]}]},{id:`nexus`,title:`A Nexus e a rede`,icon:`handshake`,items:[{id:`contact`,question:`Como falo com a equipe da Nexus?`,answer:[`Em Mais, toque em Falar com a Nexus: aplicativo, WhatsApp, telefone ou e-mail, com o prazo de resposta de cada um.`],link:{label:`Falar com a Nexus`,path:`/cuidador/mais/ajuda`}},{id:`service`,question:`Como peço um serviço da rede credenciada?`,answer:[`Em Rede, procure pelo que você precisa, compare os profissionais e faça o pedido pelo próprio aplicativo.`],link:{label:`Abrir a Rede`,path:`/cuidador/rede`}}]}];function d(o){return o.normalize(`NFD`).replace(/[̀-ͯ]/g,``).toLowerCase().trim()}function h(o,n,t=``){let i=d(t).split(/\s+/).filter(e=>e.length>0);return o.map(e=>m(l$1({},e),{items:e.items.filter(a=>{if(a.requires&&!n(a.requires))return!1;if(i.length===0)return!0;let u=d([a.question,...a.answer,...a.list??[]].join(` `));return i.every(m=>u.includes(m))})})).filter(e=>e.items.length>0)}export{p as i,h as n,l as r,c as t};